class Solution {
private:
    struct HashPair {
        long long h1, h2;
        bool operator==(const HashPair& o) const { return h1 == o.h1 && h2 == o.h2; }
    };
    struct HashPairOp {
        size_t operator()(const HashPair& p) const { return hash<long long>()(p.h1) ^ (hash<long long>()(p.h2) << 16); }
    };

    long long modPow(long long base, long long exp, long long mod) {
        long long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }

    bool check(int L, const vector<vector<int>>& paths) {
        const long long BASE1 = 100003, MOD1 = 1000000007;
        const long long BASE2 = 100019, MOD2 = 1000000009;
        long long b1Pow = modPow(BASE1, L, MOD1);
        long long b2Pow = modPow(BASE2, L, MOD2);

        unordered_set<HashPair, HashPairOp> common;
        bool isFirst = true;

        for (const auto& p : paths) {
            long long h1 = 0, h2 = 0;
            for (int i = 0; i < L; i++) {
                h1 = (h1 * BASE1 + p[i]) % MOD1;
                h2 = (h2 * BASE2 + p[i]) % MOD2;
            }
            unordered_set<HashPair, HashPairOp> seen;
            seen.insert({h1, h2});
            for (int i = L; i < p.size(); i++) {
                h1 = (h1 * BASE1 + p[i] - p[i - L] * b1Pow) % MOD1;
                if (h1 < 0) h1 += MOD1;
                h2 = (h2 * BASE2 + p[i] - p[i - L] * b2Pow) % MOD2;
                if (h2 < 0) h2 += MOD2;
                seen.insert({h1, h2});
            }

            if (isFirst) {
                common = std::move(seen);
                isFirst = false;
            } else {
                unordered_set<HashPair, HashPairOp> nextCommon;
                for (const auto& item : seen) {
                    if (common.find(item) != common.end()) nextCommon.insert(item);
                }
                common = std::move(nextCommon);
            }
            if (common.empty()) return false;
        }
        return !common.empty();
    }

public:
    int longestCommonSubpath(int n, vector<vector<int>>& paths) {
        int low = 1, high = paths[0].size();
        for (const auto& p : paths) high = min(high, (int)p.size());
        int ans = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid, paths)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    private long modPow(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }

    private boolean check(int L, int[][] paths) {
        long BASE1 = 100003, MOD1 = 1000000007;
        long BASE2 = 100019, MOD2 = 1000000009;
        long b1Pow = modPow(BASE1, L, MOD1);
        long b2Pow = modPow(BASE2, L, MOD2);

        Set<Long> common = null;
        for (int[] p : paths) {
            long h1 = 0, h2 = 0;
            for (int i = 0; i < L; i++) {
                h1 = (h1 * BASE1 + p[i]) % MOD1;
                h2 = (h2 * BASE2 + p[i]) % MOD2;
            }
            Set<Long> seen = new HashSet<>();
            seen.add((h1 << 32) | (h2 & 0xFFFFFFFFL));
            for (int i = L; i < p.length; i++) {
                h1 = (h1 * BASE1 + p[i] - p[i - L] * b1Pow) % MOD1;
                if (h1 < 0) h1 += MOD1;
                h2 = (h2 * BASE2 + p[i] - p[i - L] * b2Pow) % MOD2;
                if (h2 < 0) h2 += MOD2;
                seen.add((h1 << 32) | (h2 & 0xFFFFFFFFL));
            }

            if (common == null) {
                common = seen;
            } else {
                common.retainAll(seen);
            }
            if (common.isEmpty()) return false;
        }
        return common != null && !common.isEmpty();
    }

    public int longestCommonSubpath(int n, int[][] paths) {
        int low = 1, high = paths[0].length;
        for (int[] p : paths) high = Math.min(high, p.length);
        int ans = 0;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (check(mid, paths)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
}

var longestCommonSubpath = function(n, paths) {
  let low = 1, high = paths[0].length;
  for (const p of paths) high = Math.min(high, p.length);

  const MOD1 = 1000000007n;
  const MOD2 = 1000000009n;
  const BASE1 = 100003n;
  const BASE2 = 100019n;

  function modPow(base, exp, mod) {
    let res = 1n;
    base %= mod;
    while (exp > 0n) {
      if (exp % 2n === 1n) res = (res * base) % mod;
      base = (base * base) % mod;
      exp /= 2n;
    }
    return res;
  }

  function check(L) {
    const b1Pow = modPow(BASE1, BigInt(L), MOD1);
    const b2Pow = modPow(BASE2, BigInt(L), MOD2);
    let common = null;

    for (const p of paths) {
      let h1 = 0n, h2 = 0n;
      for (let i = 0; i < L; i++) {
        h1 = (h1 * BASE1 + BigInt(p[i])) % MOD1;
        h2 = (h2 * BASE2 + BigInt(p[i])) % MOD2;
      }
      const seen = new Set();
      seen.add(`${h1},${h2}`);
      for (let i = L; i < p.length; i++) {
        h1 = (h1 * BASE1 + BigInt(p[i]) - BigInt(p[i - L]) * b1Pow) % MOD1;
        if (h1 < 0n) h1 += MOD1;
        h2 = (h2 * BASE2 + BigInt(p[i]) - BigInt(p[i - L]) * b2Pow) % MOD2;
        if (h2 < 0n) h2 += MOD2;
        seen.add(`${h1},${h2}`);
      }

      if (common === null) {
        common = seen;
      } else {
        const nextCommon = new Set();
        for (const item of seen) {
          if (common.has(item)) nextCommon.add(item);
        }
        common = nextCommon;
      }
      if (common.size === 0) return false;
    }
    return common && common.size > 0;
  }

  let ans = 0;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (check(mid)) {
      ans = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return ans;
};
